@extends('layouts.app') @section('title',$post->exists?'Edit post':'Create post') @section('content')<section class="page"><h1>{{ $post->exists?'Edit post':'Create post' }}</h1>@include('dashboard._nav')<form class="form-grid panel" method="post" action="{{ $post->exists?route('dashboard.posts.update',$post):route('dashboard.posts.store') }}">@csrf @if($post->exists)@method('put')@endif<input name="title" value="{{ old('title',$post->title) }}" placeholder="Headline" required><select name="category_id"><option value="">Choose category</option>@foreach($categories as $category)<option value="{{ $category->_id }}" @selected(old('category_id',$post->category_id)==(string)$category->_id)>{{ $category->category_name }}</option>@endforeach</select><input name="image" value="{{ old('image',$post->image) }}" placeholder="Image path (posts/photo.jpg)"><textarea name="content" style="min-height:360px" placeholder="Write the story..." required>{{ old('content',$post->content) }}</textarea><select name="status"><option value="draft">Draft</option><option value="pending" @selected($post->status==='pending')>Pending</option><option value="published" @selected($post->status==='published')>Published</option></select><button>Save post</button></form></section>@endsection
